select ok(check_value, description) from (values
  ((select source_kind='NEED_GENERATION' from atlas_planning.confirmed_need_batches where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'school-catering batch is typed NEED_GENERATION'),
  ((select wholesale_order_id is null from atlas_planning.confirmed_need_batches where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'Need Generation batch has no Wholesale source'),
  ((select num_nonnulls(origin_need_generation_run_id,origin_need_generation_run_version,origin_need_generation_release_snapshot_id,current_need_generation_run_id,current_need_generation_run_version,current_need_generation_release_snapshot_id)=6 from atlas_planning.confirmed_need_batches where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'batch has both complete release triples'),
  ((select row(origin_need_generation_run_id,origin_need_generation_run_version,origin_need_generation_release_snapshot_id)=row(current_need_generation_run_id,current_need_generation_run_version,current_need_generation_release_snapshot_id) from atlas_planning.confirmed_need_batches where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'current release initially equals origin'),
  ((select row(batch.period_start,batch.period_end)=row(run.period_start,run.period_end) from atlas_planning.confirmed_need_batches batch join atlas_planning.need_generation_runs run on run.need_generation_run_id=batch.origin_need_generation_run_id where batch.confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'batch period equals source run'),
  ((select run_status='RELEASED_FOR_CONFIRMATION' from atlas_planning.need_generation_runs where need_generation_run_id='b6300000-0000-0000-0000-000000000500'),'source run is released'),
  ((select released_run_version=3 from atlas_planning.need_generation_release_snapshots where need_generation_release_snapshot_id='b6300000-0000-0000-0000-000000000540'),'source snapshot binds exact version'),
  ((select count(*)=2 from atlas_planning.confirmed_need_lines where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'two stable lines exist'),
  ((select count(*)=2 from atlas_planning.confirmed_need_lines where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600' and source_kind='NEED_GENERATION'),'line source kinds agree'),
  ((select count(*)=2 from atlas_planning.confirmed_need_lines where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600' and wholesale_order_line_id is null),'Need Generation lines omit Wholesale source'),
  ((select count(*)=2 from atlas_planning.confirmed_need_lines where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600' and num_nonnulls(service_date,customer_id,school_id,delivery_location_id,ingredient_id,controlled_unit_id)=6),'line operational tuples are complete'),
  ((select count(distinct row(service_date,customer_id,school_id,delivery_location_id,ingredient_id,controlled_unit_id))=2 from atlas_planning.confirmed_need_lines where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'operational tuples are distinct'),
  ((select count(*)=2 from atlas_planning.confirmed_need_lines line join atlas_admin.schools school on (school.customer_id,school.school_id)=(line.customer_id,line.school_id) where line.confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'School ownership is exact'),
  ((select count(*)=2 from atlas_planning.confirmed_need_lines line join atlas_admin.delivery_locations location on (location.customer_id,location.delivery_location_id)=(line.customer_id,line.delivery_location_id) where line.confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'destination ownership is exact'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revisions where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'two revisions exist'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revisions where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600' and source_kind='NEED_GENERATION'),'revision source kinds agree'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revisions where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600' and wholesale_order_line_revision_id is null),'Need Generation revisions omit Wholesale source'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revisions where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600' and need_generation_release_snapshot_id='b6300000-0000-0000-0000-000000000540'),'revisions bind origin snapshot'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revisions revision join atlas_planning.confirmed_need_lines line using(confirmed_need_line_id) where revision.confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600' and row(revision.service_date,revision.customer_id,revision.school_id,revision.delivery_location_id,revision.ingredient_id,revision.unit_id)=row(line.service_date,line.customer_id,line.school_id,line.delivery_location_id,line.ingredient_id,line.controlled_unit_id)),'revision tuples equal stable-line tuples'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revisions revision join atlas_planning.confirmed_need_batches batch using(confirmed_need_batch_id) where revision.is_current and row(revision.need_generation_run_id,revision.need_generation_run_version,revision.need_generation_release_snapshot_id)=row(batch.current_need_generation_run_id,batch.current_need_generation_run_version,batch.current_need_generation_release_snapshot_id)),'current revisions equal controlled release'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revision_contributions where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'two exact source members exist'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revision_contributions where source_unit_id=controlled_unit_id),'no-conversion Unit equality holds'),
  ((select count(distinct ingredient_id)=2 from atlas_planning.confirmed_need_lines where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'different Ingredients form different lines'),
  ((select count(distinct row(confirmed_need_batch_id,service_date,customer_id,school_id,delivery_location_id,ingredient_id,controlled_unit_id))=2 from atlas_planning.confirmed_need_lines where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600'),'seven-part identity is exact'),
  (not exists(select 1 from information_schema.columns where table_schema='atlas_planning' and table_name='confirmed_need_lines' and column_name in('dish_id','recipe_id','weekly_menu_id')),'stable identity excludes Dish Recipe and Menu'),
  (not exists(select 1 from information_schema.columns where table_schema='atlas_planning' and table_name='confirmed_need_lines' and column_name='theoretical_need_line_id'),'stable identity excludes singular Theoretical Need'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revisions where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600' and is_current),'one current revision exists per line'),
  ((select count(*)=2 from atlas_planning.confirmed_need_line_revisions where confirmed_need_batch_id='b6300000-0000-0000-0000-000000000600' and theoretical_quantity=confirmed_quantity),'Draft confirmed proposals are separately retained'),
  ((select indexdef ~ 'controlled_unit_id' from pg_indexes where schemaname='atlas_planning' and indexname='confirmed_need_lines_operational_identity_key'),'controlled Unit is part of identity'),
  ((select indexdef !~ 'dish_id|recipe_id|theoretical_need_line_id' from pg_indexes where schemaname='atlas_planning' and indexname='confirmed_need_lines_operational_identity_key'),'forbidden upstream detail is absent from identity')
) checks(check_value,description);

